import os, zlib, base64, re

def get_pdf_text(path):
    try:
        with open(path, 'rb') as f:
            data = f.read()
        idx1 = data.find(b'stream')
        idx2 = data.find(b'endstream')
        if idx1 != -1 and idx2 != -1:
            s = data[idx1+6:idx2].strip()
            if not s.endswith(b'~>'):
                s = s + b'~>'
            decoded = base64.a85decode(s, adobe=True)
            decomp = zlib.decompress(decoded)
            raw = decomp.decode('latin1', errors='ignore')
            # Extract all text inside parentheses
            strings = re.findall(r'\\((.*?)\\)', raw)
            return ' '.join(strings)
    except Exception as e:
        return f'Error: {e}'
    return ''

for root, dirs, files in os.walk('company_files'):
    for f in sorted(files):
        if f.endswith('.pdf'):
            full_path = os.path.join(root, f)
            txt = get_pdf_text(full_path)
            if any(k in txt.lower() or k in f.lower() for k in ['4c', 'mesa', 'castillo', 'linda']):
                print(f'=== {full_path} ===')
                print(txt)
